const p=t=>`<p>${t}</p>`;
const list=a=>`<ul>${a.map(t=>`<li>${t}</li>`).join('')}</ul>`;
const table=(heads,rows)=>`<div class="table-wrap"><table><thead><tr>${heads.map(t=>`<th>${t}</th>`).join('')}</tr></thead><tbody>${rows.map(r=>`<tr>${r.map(t=>`<td>${t}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;
const note=(title,t)=>`<aside class="note"><strong>${title}</strong>${p(t)}</aside>`;
const section=(title,body)=>`<section class="lesson-section"><h2>${title}</h2>${body}</section>`;
const example=(t,b)=>`<div class="example"><span class="eyebrow">ตัวอย่าง</span><h3>${t}</h3>${b}</div>`;
const refs=(items)=>`<div class="references"><strong>อ่านเทียบกับเอกสาร</strong>${items.map(([id,pages])=>`<p><a href="#sources" data-source="${id}">${SOURCE_NAMES[id]||id}</a>${pages?' · หน้า '+pages:''}</p>`).join('')}</div>`;
const SOURCE_NAMES={5:'L1 · SE Foundation & Software Project Management',7:'L2 · Software Process Models',8:'L3 · Requirements Engineering',11:'L4 · Use Case Modeling',14:'L6 · Flow Modeling I',15:'L7 · Flow Modeling II',18:'L8 · User Interface Design',19:'Midterm Guideline',1:'Lab 3 · Requirements (PHTRS)',2:'Lab 4 · Use Case (PHTRS)',3:'Lab 6 · Context DFD (PHTRS)',9:'In-class · Zoo Ticketing',12:'Exercise 2 · Clinic & POS',16:'Exercise 3 · Zoo Flow Modeling (ใน ZIP)',21:'งาน Ex2 · Clinic & POS',22:'งาน Ex3 · Zoo DFD',25:'Context Diagram Answer · Studio',26:'Context Diagram Exercise · Studio',27:'สรุป Software Process Models',29:'สรุป Use Case / SRS / Requirements Management',31:'Software Engineering Quiz Practice · UEBS'};
const LESSONS=[
{id:'foundation',no:'01',title:'Software Engineering Foundation',thai:'พื้นฐานวิศวกรรมซอฟต์แวร์',part:1,time:'12',summary:'Software คืออะไร ทำไมต้องใช้ Engineering และใครทำหน้าที่อะไร',content:
section('เริ่มจากปัญหาธุรกิจ ไปสู่ซอฟต์แวร์',p('Business need คือเหตุผลที่ต้องเปลี่ยนแปลง → Business process คือวิธีทำงาน → Software development คือการสร้างระบบมาช่วยให้วิธีทำงานมีประสิทธิภาพ แม่นยำ และรองรับงานมากขึ้น')+example('ร้านอาหารรับจองโต๊ะทางโทรศัพท์',table(['มุมมอง','ตัวอย่าง'],[['Business need','ลดการจองซ้ำและลดงานรับโทรศัพท์'],['Business process','ลูกค้าเลือกเวลา → ตรวจโต๊ะว่าง → ยืนยันการจอง'],['Software','เว็บจองโต๊ะตรวจเวลาว่างและบันทึกการจองให้พนักงาน']])) )+
section('Software มี 3 องค์ประกอบ',list(['<b>Programs / instructions:</b> ชุดคำสั่งที่สร้างฟังก์ชันและพฤติกรรม','<b>Data structures:</b> โครงสร้างข้อมูลที่โปรแกรมจัดการ','<b>Documentation:</b> คำอธิบายการทำงาน การใช้ และการดูแลระบบ'])+p('ตัวอย่างระบบตั๋ว: โค้ดขายตั๋ว + ข้อมูลตั๋ว/Booking + คู่มือผู้ใช้และเอกสารระบบ')+note('ลักษณะที่ต้องจำ','Software ถูกพัฒนา/ออกแบบ ไม่ได้ผลิตแบบฮาร์ดแวร์ จับต้องไม่ได้ ใช้แรงงานความรู้มาก เปลี่ยนแปลงอาจยาก ไม่สึกหรอทางกายภาพ แต่ล้าสมัยได้เมื่อสภาพแวดล้อมหรือความต้องการเปลี่ยน'))+
section('Software Engineering คืออะไร',p('การแก้ปัญหาของลูกค้าด้วยการพัฒนาและวิวัฒนาการซอฟต์แวร์อย่างเป็นระบบ ให้มีคุณภาพ ภายใต้ข้อจำกัดด้านเวลา งบประมาณ และทรัพยากร')+table(['คำสำคัญ','ความหมาย'],[['Customer problems','สร้างสิ่งที่ตอบโจทย์ผู้ใช้'],['Systematic development & evolution','มีวิธีทำงาน การตรวจสอบ และการดูแลต่อเนื่อง'],['Quality & complexity','จัดการความซับซ้อนและคุณภาพ'],['Constraints','คุม scope / time / cost และข้อจำกัดอื่น']])+p('Process = ชุดกิจกรรมที่ทำงาน · Product = ผลงาน เช่น ระบบและเอกสาร · Engineering = หลักการที่ใช้ทำให้ผลงานมีคุณภาพอย่างเป็นระบบ'))+
section('บทบาทในโครงการ',table(['บทบาท','สิ่งที่รับผิดชอบ'],[['Customer / Sponsor','กำหนด business need สนับสนุนงบ และอนุมัติผลงาน'],['End user','ใช้งานจริง ให้ข้อมูลการทำงานและ usability'],['Project Manager (PM)','วางแผน scope เวลา คน งบ ติดตามงานและความเสี่ยง'],['Business Analyst (BA)','เก็บ วิเคราะห์ และตรวจสอบ requirements เป็นสะพานระหว่างลูกค้ากับทีม'],['System Analyst (SA)','แปลง requirements ไปสู่รายละเอียดทางเทคนิคและโครงสร้างระบบ ตามบทบาทที่สไลด์ใช้'],['Developer','เขียนโค้ด ทดสอบหน่วย แก้ข้อบกพร่องและรวมส่วนประกอบ'],['UX/UI Designer','วิจัยผู้ใช้ ออกแบบ wireframe/mockup/prototype'],['QA / Tester','สร้าง test cases ทดสอบ รายงาน defect และตรวจการแก้ไข']]))+
section('คุณภาพ ความซับซ้อน และการทำงานเป็นทีม',list(['คุณภาพตัวอย่าง: Usability, Efficiency, Testability, Maintainability, Reusability ต้องเลือกวิธีวัดให้เหมาะกับเป้าหมาย','Breadth = จำนวนฟังก์ชัน/ผู้ใช้/การเชื่อมต่อ · Depth = ความซ้อนและความสัมพันธ์ต่อกัน ยิ่งมากยิ่งซับซ้อน','Technical issues: process, methodology, tools, platform, language, database, network, configuration management','Non-technical issues: estimation, schedule, assignment, communication, risk','ปัจจัยสำเร็จ: ผู้ใช้มีส่วนร่วม ผู้บริหารสนับสนุน requirements ชัด แผนสมจริง ทีมมีความเชี่ยวชาญและงบเพียงพอ'])+example('เพิ่มคน ไม่ได้ทำให้งานเร็วเสมอ',p('ช่องทางสื่อสารแบบทุกคู่ = n(n−1)/2 คน 4 คนมี 6 คู่ คน 6 คนมี 15 คู่ จึงมีต้นทุนการประสานงานและโอกาสสื่อสารผิดเพิ่มขึ้น')))+
section('พื้นฐานการทดสอบและการสนับสนุน',table(['แนวคิด','ต้องแยกให้ได้'],[['Unit testing','ทดสอบส่วนย่อยของโปรแกรม'],['Acceptance testing','ตรวจว่าระบบตรงความต้องการที่ลูกค้ายอมรับ'],['Black-box','ดู input/output โดยไม่ใช้โครงสร้างโค้ด'],['White-box','ใช้โครงสร้างและเส้นทางของโค้ดในการออกแบบการทดสอบ']])+p('ก่อนปล่อยระบบต้องเตรียมอบรมและ support หลังปล่อยต้องรับปัญหา แก้ defect และปรับฟังก์ชันตามความต้องการ'))+refs([[5,'5–44'],[19,'3–7']])},
{id:'project',no:'02',title:'Software Project Management',thai:'บริหารโครงการให้ตรงเป้าหมาย',part:1,time:'12',summary:'Triple constraint, 4P, POMA, WBS, Gantt และการวางแผน',content:
section('Project ต่างจาก Operations',p('Project คือความพยายามชั่วคราวเพื่อสร้างผลลัพธ์ที่มีลักษณะเฉพาะ มีจุดเริ่มและสิ้นสุด ส่วน Operations เป็นงานต่อเนื่องที่ทำให้ธุรกิจดำเนินไปได้')+example('ระบบจองตั๋ว',p('พัฒนาเว็บขายตั๋วเวอร์ชันแรก = Project · ให้บริการขายตั๋วและดูแลระบบประจำวัน = Operations'))+list(['Project มีเป้าหมายเฉพาะ ใช้ทรัพยากร มีลูกค้าหรือ sponsor และมีความไม่แน่นอน','SPM เป็น umbrella activity เริ่มก่อนงานเทคนิคและดำเนินตลอดการพัฒนา ไม่ใช่ Software Development Process']))+
section('Scope · Time · Cost',p('Triple constraint คือขอบเขตงาน เวลา และต้นทุน การเปลี่ยนหนึ่งด้านอาจกระทบด้านอื่นและคุณภาพ จึงต้องประเมินก่อนตัดสินใจ')+example('เพิ่มระบบคืนเงินก่อนส่งงาน 1 สัปดาห์',p('ต้องประเมินว่ามีงานเพิ่มเท่าใด เลื่อนส่งหรือเพิ่มทรัพยากรได้หรือไม่ และกระทบ testing อย่างไร ไม่ควรลดการตรวจสอบจนคุณภาพไม่ผ่าน'))+table(['4P ตามสไลด์','มองอะไร'],[['People','บทบาทและทักษะของคน'],['Problem','วัตถุประสงค์ scope ทางเลือก และข้อจำกัด'],['Process','tasks, milestones, deliverables, QA'],['Project','การประสานและจัดการโครงการทั้งหมด']]))+
section('POMA จำจากสิ่งที่ทำ',table(['ขั้น','งานสำคัญ','ตัวอย่าง'],[['Planning','เข้าใจ requirements ตั้งเป้าหมายที่วัดได้ ประเมินงาน เวลา คน งบและความเสี่ยง','วางแผนทำระบบตั๋ว 6 สัปดาห์'],['Organizing','จัดโครงสร้างทีม รับคน อบรม ตั้งกลไกติดตาม','แบ่ง BA / UI / Dev / QA และผู้รับผิดชอบ'],['Monitoring','เก็บสถานะ → วิเคราะห์ → สื่อสารผล','พบงานชำระเงินล่าช้า 3 วัน'],['Adjusting','ปรับ resource, schedule หรือ project content','ปรับแผนและตกลงลด scope บางส่วน']])+note('กับดักข้อสอบ','POMA อาจดูเรียงกันในระดับภาพรวม แต่ในงานจริงต้องวนติดตามและปรับ ไม่ใช่ทำครั้งเดียวแล้วจบ'))+
section('WBS, Gantt และ Network diagram',table(['เครื่องมือ','ช่วยเรื่องใด'],[['WBS (Work Breakdown Structure)','แตกขอบเขต/ผลส่งมอบเป็นงานย่อย เพื่อประเมินและมอบหมาย'],['Gantt chart','แสดงงานบนเส้นเวลาและช่วงเวลาที่ทำ'],['Network / PERT','แสดงงานและ dependency ที่ต้องทำก่อนหลัง'],['Critical path','เส้นทางงานที่กำหนดระยะเวลาสิ้นสุดของโครงการ ไม่มีเวลายืดหยุ่นบนเส้นทางนั้นตามแผน']])+example('WBS ระบบขายตั๋ว',list(['Requirements: เก็บข้อมูลผู้ใช้ → สรุป FR/NFR → ตรวจสอบกับผู้เกี่ยวข้อง','Development: ซื้อบัตร / ชำระเงิน / จัดการบัตร / รายงาน','Testing: test cases → ทดสอบ → แก้ defect','Deployment & documentation: ส่งมอบ อบรม คู่มือ'])+p('จากนั้นจัดลำดับ ประเมินเวลา และระบุคนรับผิดชอบ ไม่ใช่เพียงสร้างรายชื่อฟังก์ชัน')))+
section('ตัวอย่างคำนวณเวลาแบบง่าย',p('สมมติ A เก็บ requirements 2 วัน → ทำ B ออกแบบหน้าจอ 3 วัน และ C เตรียมข้อมูล 4 วันพร้อมกัน → D รวมระบบ 2 วัน')+note('ระยะเวลารวม','2 + max(3,4) + 2 = 8 วัน · Critical path = A → C → D ส่วน B มี slack 1 วัน ตัวเลขเป็นตัวอย่างเสริมเพื่ออธิบาย dependency'))+
section('Knowledge areas และความสำเร็จ',p('10 areas ใน L1: Integration, Scope, Schedule, Cost, Quality, Resource, Communications, Risk, Procurement, Stakeholder')+p('โครงการสำเร็จต้องดูทั้ง scope/time/cost ความพึงพอใจของลูกค้า และบรรลุเป้าหมายธุรกิจ เช่น ลดเวลาขายตั๋ว ไม่ใช่เพียงส่งงานทัน'))+refs([[5,'45–76'],[19,'8–14']])},
{id:'process',no:'03',title:'Software Process Models',thai:'เลือกกระบวนการให้เหมาะกับโจทย์',part:1,time:'15',summary:'Waterfall, Incremental, Spiral, Agile และ Scrum',content:
section('กระบวนการจัดระเบียบงาน คน และผลลัพธ์',p('Software process model กำหนด tasks, sequence, roles, input/output, pre/postconditions, artifacts และการประสานงาน เพื่อพัฒนาและดูแลซอฟต์แวร์อย่างมีคุณภาพ')+p('กิจกรรมร่วม: Requirements → Design → Implementation → Testing / QA → Deployment → Maintenance รูปแบบแต่ละ model ต่างกันที่การจัดลำดับ การวนซ้ำ และการส่งมอบ')+p('Layered technology ในสไลด์: Quality focus เป็นฐาน → Process → Methods → Tools · Task set มี work tasks, work products, milestones/deliverables และ QA checkpoints')+list(['Umbrella activities: project management, technical reviews, QA, configuration management, work-product preparation, reuse management, measurement, risk management']))+
section('เปรียบเทียบ Models',table(['Model','จุดเด่น / เหมาะกับ','สิ่งที่ต้องระวัง'],[['Code & Fix','เริ่มโค้ดแล้วแก้ปัญหา วงจรง่าย','requirements อาจไม่ชัด และอาจข้าม unit test/debug'],['Waterfall','ทำเป็น phase ต่อเนื่อง เน้นเอกสาร เหมาะกับ requirements ชัดและคงที่','เปลี่ยนยาก ผลงานและปัญหาบางส่วนเห็นช้า'],['Incremental A','แบ่งแต่ละ requirement พัฒนา Req–Design–Code–Unit test แล้วรวมเข้า integration bucket','ต้องจัดการ interface และ integrated system test'],['Incremental B / Multiple release','แบ่ง requirements เป็นชุด แต่ละชุด package และ release','ต้องวางแผนหลาย release และ dependency'],['Spiral','วนรอบโดยวิเคราะห์และลดความเสี่ยง เหมาะกับงานไม่แน่นอน','ต้องมีทักษะ risk assessment'],['Agile','รอบสั้น ส่งของใช้งานได้ รับ feedback และปรับตัว','ต้องมีวินัย การร่วมมือ และจัดการเอกสาร/เวลา/งบ']]))+
section('Spiral: แต่ละรอบต้องตอบ 4 เรื่อง',list(['1. กำหนด objectives, alternatives, constraints','2. ประเมินทางเลือก ระบุและลด risks อาจสร้าง prototype','3. พัฒนาและตรวจสอบ product ระดับถัดไป','4. วางแผนรอบถัดไปและ review'])+example('Payment ของสวนสัตว์ยังไม่เคยเชื่อมต่อ',p('ทีมทดลอง prototype เชื่อม payment ก่อนพัฒนาระบบทั้งหมด เพื่อหาความเสี่ยงของการเชื่อมต่อ เหมาะกับแนวคิด Spiral')))+
section('Agile: คุณค่า 4 คู่',table(['ให้น้ำหนักมากกว่า','ยังมีคุณค่าเช่นกัน'],[['คนและปฏิสัมพันธ์','กระบวนการและเครื่องมือ'],['ซอฟต์แวร์ที่ใช้งานได้','เอกสารที่ครอบคลุม'],['ร่วมมือกับลูกค้า','เจรจาสัญญา'],['ตอบสนองการเปลี่ยนแปลง','ทำตามแผน']])+note('ห้ามตีความว่า “ไม่ต้องมี”','Agile ไม่ได้ห้ามเอกสาร เครื่องมือ แผน หรือสัญญา แต่จัดลำดับความสำคัญ สร้างเอกสารเท่าที่จำเป็นและมีประโยชน์')+p('เทียบแนวคิดต้นฉบับได้ที่ <a href="https://agilemanifesto.org/" target="_blank" rel="noopener">Agile Manifesto</a>'))+
section('Scrum และ Iterative vs Incremental',p('Scrum เป็น framework ในกลุ่ม Agile จัดงานเป็นรอบสั้นที่เรียกว่า Sprint ทีมร่วมกันส่งมอบและตรวจ feedback')+table(['คำ','ตัวอย่าง'],[['Iterative','ปรับปรุงหน้าซื้อบัตรเดิมจาก feedback ในรอบถัดไป'],['Incremental','เพิ่มความสามารถใหม่ เช่น รอบ 1 ซื้อบัตร รอบ 2 ยกเลิก รอบ 3 รายงาน']])+p('โครงการหนึ่งเป็นทั้ง iterative และ incremental ได้ · Agile เป็นแนวคิดกว้าง ส่วน Scrum เป็นกรอบการปฏิบัติหนึ่ง'))+
section('เลือกจากเหตุผลในโจทย์',table(['สถานการณ์สมมติ','คำตอบที่อธิบายได้'],[['Requirements ชัด มีเอกสารและ phase gate','Waterfall'],['ระบบใหญ่ แบ่งเป็นส่วน และต้องรวมทดสอบ','Incremental'],['เทคโนโลยีใหม่ มีความเสี่ยง ต้องวิเคราะห์ทุกรอบ','Spiral'],['ลูกค้าให้ feedback บ่อย ความต้องการเปลี่ยน','Agile / Scrum ตามรายละเอียดโจทย์']])+p('L2 มีกรณี CrowdStrike/Knight Capital ใช้ชี้ว่าการทดสอบและควบคุม deployment สำคัญ และเปรียบเทียบ Spotify กับ HealthCare.gov เพื่อเห็นผลของ feedback, autonomy, integration และ late testing ตามกรณีศึกษาในสไลด์')+p('Process assessment ประเมินความสมบูรณ์ของวิธีทำงานเพื่อหาเรื่องปรับปรุง สไลด์ยก ISO 9000 series และ SEI เป็นตัวอย่าง'))+refs([[7,'6–31'],[27,'1–15'],[19,'16–24']])},
{id:'requirements',no:'04',title:'Requirements Engineering',thai:'เก็บ เขียน ตรวจ และจัดการความต้องการ',part:1,time:'25',summary:'FR/NFR, Elicitation, User story, SRS, Validation และ Change',content:
section('แยก 2 มิติให้ชัด',table(['มิติ','ความหมาย','ตัวอย่าง'],[['User requirements','อธิบายบริการและข้อจำกัดด้วยภาษาผู้ใช้','ผู้เข้าชมสามารถซื้อตั๋วออนไลน์ได้'],['System requirements','รายละเอียดที่ทีมต้องนำไปพัฒนา','เมื่อชำระสำเร็จ ระบบต้องบันทึก Booking ID และออก QR Code'],['Functional (FR)','บริการ/พฤติกรรม: ระบบทำอะไร','คำนวณราคารวม ออกตั๋ว ตรวจสอบสถานะ'],['Non-functional (NFR)','คุณภาพ/ข้อจำกัด: ทำได้ดีหรือภายใต้เงื่อนไขใด','หน้าเลือกตั๋วตอบสนองภายใน 2 วินาทีสำหรับ 95% ของคำขอ']])+note('คนละแกน','User/System บอกระดับรายละเอียดและผู้รับสาร ส่วน FR/NFR บอกชนิดความต้องการ System requirement จึงมีได้ทั้ง FR และ NFR'))+
section('NFR ต้องชัด วัดได้ และตรวจสอบได้',table(['ด้าน','ตัวอย่างเสริมที่วัดผลได้'],[['Performance','95% ของคำขอแสดงรายการตั๋ว ≤ 2 วินาที ภายใต้ผู้ใช้พร้อมกัน 500 คน'],['Availability','พร้อมใช้งานอย่างน้อย 99.5% ต่อเดือน ตามช่วงบริการที่ตกลง'],['Usability','ผู้ใช้ใหม่อย่างน้อย 90% ซื้อตั๋วสำเร็จ ≤ 3 นาทีในการทดสอบงานที่กำหนด'],['Compatibility','ขั้นตอนซื้อบัตรทำงานครบบน Chrome/Edge และ Safari เวอร์ชันที่กำหนดใน test plan'],['Security','ผู้ใช้ไม่มีสิทธิ์ต้องเข้าถึงข้อมูลการจองของผู้อื่นไม่ได้ในทุกกรณีทดสอบที่กำหนด'],['Resource / Space','หน่วยความจำสูงสุดของบริการไม่เกินงบทรัพยากรที่ระบุระหว่าง load test']])+p('ตัวเลขข้างต้นเป็นข้อเสนอสำหรับฝึกเขียน ไม่ใช่ข้อกำหนดจากโจทย์สวนสัตว์')+p('กลุ่ม NFR ใน L3: Product (usability, efficiency, dependability, security), Organizational (environmental, operational, development), External (regulatory, ethical, legislative)')+note('Security อาจเขียนได้หลายระดับ','“จำกัดการเข้าถึงเฉพาะหัวหน้า” เป็น security constraint แต่ “ระบบต้องตรวจ role แล้วปฏิเสธคำขอที่ไม่มีสิทธิ์” อธิบายพฤติกรรมที่เป็น FR ได้ พิจารณาข้อความและระดับของ requirement ไม่ตัดสินจากคำว่า security เพียงอย่างเดียว'))+
section('RE เป็นกระบวนการวนซ้ำ',p('Feasibility study มาก่อนหรือในช่วงต้น: ตอบว่าเข้ากับเป้าหมายองค์กรหรือไม่ ทำได้ด้วยเทคโนโลยี เวลา งบที่มีหรือไม่ และเชื่อมระบบเดิมได้หรือไม่')+table(['ขั้น','ผลที่ต้องได้'],[['Elicitation','เข้าใจงานจริงและความต้องการของ stakeholders'],['Specification','บันทึก user/system requirements ให้ชัดและเป็นระบบ'],['Validation','ตรวจว่า requirements ตรงสิ่งที่ลูกค้าต้องการและใช้ได้'],['Requirements change','ติดตามและจัดการการเปลี่ยนแปลง']])+p('6 dimensions ของ elicitation: Individual functionality, Business workflow, Data/formats, UI, Existing/system interfaces, Other constraints เช่น performance/reliability'))+
section('เลือกเทคนิค Elicitation',table(['เทคนิค','เมื่อใด / ข้อจำกัด'],[['Interview','ถามเป้าหมายและเหตุผล · Closed มีคำถาม/คำตอบที่เตรียมไว้ Open เปิดประเด็น · ระวัง jargon และงานที่ผู้ใช้คิดว่าไม่ต้องอธิบาย'],['Ethnography / Observation','ดูงานจริงเพื่อพบ implicit requirements ที่คนอาจไม่พูดในการสัมภาษณ์'],['Existing documents/forms/databases','ดูข้อมูลและ workflow เดิม'],['Questionnaire','รับข้อมูลจากผู้ใช้จำนวนมาก แต่รายละเอียดและการถามต่อจำกัด'],['Research / Site visit','เรียนรู้ domain และสภาพแวดล้อม'],['JRP','ประชุมผู้เกี่ยวข้องร่วมกันเพื่อทำความเข้าใจ/ตกลง requirements']])+p('ความท้าทาย: ผู้ใช้ไม่แน่ใจว่าต้องการอะไร อธิบายยาก ขอสิ่งที่ทำไม่ได้ หรือ stakeholder มีความต้องการขัดกัน BA ต้องช่วยถามและประสาน'))+
section('เขียน Specification และ User story',p('Specification อาจใช้ natural language, structured specification, graphical models หรือ formal specification เลือกให้ผู้อ่านเข้าใจได้ ใช้ ID แยกข้อความและหลีกเลี่ยงคำกำกวม')+p('Structured requirement มี ID, Type, Description, Rationale, Source, Inputs, Outputs, Action, Precondition, Postcondition')+example('User story ระบบรายงานถนน',p('<b>As a</b> ประชาชน <b>I want</b> รายงานถนนชำรุด <b>So that</b> หน่วยงานรับทราบและฉันติดตามสถานะได้')+table(['Given','When','Then'],[['ผู้ใช้เข้าสู่ระบบและเปิดแบบฟอร์ม','กรอกพิกัด/ความรุนแรงครบแล้วส่ง','ระบบบันทึกรายงานและแสดง Report ID'],['ผู้ใช้เปิดแบบฟอร์ม','ไม่ระบุพิกัดแล้วกดส่ง','ระบบแจ้งข้อมูลที่ขาดและไม่สร้างรายการ']]))+note('Acceptance criteria','เงื่อนไขของ story ต้องมีผลลัพธ์ที่ตรวจสอบได้ ส่วน Definition of Done เป็นมาตรฐานความเสร็จของงานที่ทีมตกลง ไม่ควรใช้แทนกันโดยไม่อธิบาย แม้สไลด์จะนำเสนอร่วมกัน'))+
section('SRS เป็นข้อตกลงกลาง',p('<b>Software Requirements Specification</b> คือข้อความทางการของสิ่งที่ต้องพัฒนา มีทั้ง user และ system requirements ใช้ร่วมกันในการออกแบบ พัฒนา ทดสอบ วางแผน ดูแล และควบคุม scope creep')+table(['ผู้อ่าน','ใช้เพื่อ'],[['Customers','ตรวจความตรงตามความต้องการ'],['Managers','ประเมินงาน คน งบ และแผน'],['System engineers','เข้าใจสิ่งที่ต้องสร้าง'],['Test engineers','สร้าง test cases / validation tests'],['Maintenance engineers','เข้าใจระบบและผลกระทบของการเปลี่ยนแปลง']])+table(['โครงสร้าง 10 ส่วนตาม L3','หน้าที่'],[['Preface','ผู้อ่าน เวอร์ชันและประวัติการแก้ไข'],['Introduction','เหตุผล เป้าหมาย ภาพรวมบริการและการเชื่อมต่อ'],['Glossary','นิยามศัพท์'],['User requirements definition','บริการและข้อจำกัดในภาษาลูกค้า'],['System architecture','ภาพรวม modules และการกระจายฟังก์ชัน'],['System requirements specification','FR/NFR และ interfaces แบบละเอียด'],['System models','โมเดลเพื่ออธิบายระบบ'],['System evolution','สมมติฐานและสิ่งที่อาจเปลี่ยนในอนาคต'],['Appendices','รายละเอียดเสริม เช่น hardware/database'],['Index','ดัชนีค้นหา']]))+
section('Validation: 7 คำที่ออกเป็นสถานการณ์ได้',table(['เกณฑ์','ถามอะไร','ตัวอย่างปัญหา'],[['Validity','ตรงความต้องการจริงไหม','ลูกค้าขอ reset ทาง Email แต่เอกสารกำหนด SMS'],['Consistency','ข้อกำหนดขัดกันไหม','Password ≥ 8 ตัว กับต้องเท่ากับ 6 ตัว'],['Completeness','ฟังก์ชัน/ข้อจำกัดครบไหม','มี checkout แต่ไม่ระบุ payment'],['Realism','ทำได้ด้วยข้อจำกัดไหม','งบ/เทคโนโลยีที่มีทำ performance เป้าหมายไม่ได้'],['Clarity','ตีความตรงกันไหม','“ตอบสนองเร็ว” ไม่กำหนดว่าเร็วเท่าใด'],['Verifiability','ออกแบบการทดสอบซ้ำได้ไหม','“ใช้ง่ายที่สุด” ไม่มีเกณฑ์ผ่าน'],['Traceability','ตามที่มาและผลกระทบได้ไหม','ไม่มี ID/source หรือ links ไปฟังก์ชันและ test']])+p('ข้อเดียวอาจผิดหลายเกณฑ์ได้ เช่น “ใช้ง่าย” ทั้งกำกวมและทดสอบยาก ข้อสอบต้องดูว่าปัญหาที่โจทย์เน้นคืออะไร การพบ requirement ผิดช้าทำให้ต้องแก้ design/code และ retest มากขึ้น'))+
section('Change และ Requirements management',p('ความเข้าใจปัญหาพัฒนาขึ้น ธุรกิจ/ผู้ใช้/สิ่งแวดล้อมเปลี่ยน จึงต้องคุม requirements ที่เปลี่ยนได้ ปัญหาซับซ้อนแบบ wicked problem อาจนิยามให้ครบตั้งแต่เริ่มได้ยาก')+table(['Management planning: 4 เรื่อง','สิ่งที่กำหนด'],[['Identification','ให้แต่ละ requirement มี unique ID'],['Change process','ขั้นตอนประเมินและตัดสินการเปลี่ยน'],['Traceability policies','ความสัมพันธ์ที่ต้องติดตาม'],['Tool support','เครื่องมือจัดการ version, links, history']])+table(['Change management: 3 ขั้น','ตัวอย่างเพิ่มช่องทาง payment'],[['Problem analysis & change specification','เหตุผลและขอบเขตคำขอ เปลี่ยนอะไร คำขอ valid หรือไม่'],['Change analysis & costing','กระทบ FR, UI, gateway, test ใด เวลา/งบเท่าใด'],['Change implementation','เมื่ออนุมัติ แก้ SRS/model/design/code และทดสอบใหม่']])+note('Traceability ช่วยอะไร','เชื่อม Business need → FR ID → Use case → Design → Test เพื่อประเมินสิ่งที่ต้องเปลี่ยนเมื่อ requirement เปลี่ยน'))+refs([[8,'5–66'],[1,'2–5'],[29,'8–26']])},
{id:'ui',no:'05',title:'User Interface Design',thai:'ออกแบบหน้าตาและลำดับการใช้งาน',part:1,time:'12',summary:'UI process, Golden rules และ Low/High fidelity',content:
section('UI มีทั้ง Flow และ Look & Feel',p('Flow of interactions คือผู้ใช้ทำอะไร ต่อไปที่ไหน และได้รับ feedback อย่างไร ส่วน Look & Feel คือรูปลักษณ์ ตำแหน่ง สี ขนาดและการรับรู้ขององค์ประกอบ')+table(['ชนิด Interface','ตัวอย่าง'],[['CLI','พิมพ์คำสั่ง'],['Text menu','เลือกเมนูตัวหนังสือด้วยปุ่ม/เลข'],['GUI','หน้าต่าง ปุ่ม ไอคอน'],['Touchscreen','สัมผัสและ gesture บนหน้าจอ'],['VUI','สั่งด้วยเสียง'],['Gesture / AR / VR','ปฏิสัมพันธ์ด้วยท่าทาง หรือในสภาพแวดล้อมผสม/เสมือน']])+p('UI ที่ดีควรชัด ใช้ง่าย ตอบสนองเร็ว สม่ำเสมอ และเหมาะกับผู้ใช้'))+
section('กระบวนการ 4 Phase',table(['ขั้น','คำถามที่ต้องตอบ'],[['1. User, task, environment analysis & modeling','ใครใช้ มีทักษะอะไร ทำงานอะไร ใช้ขณะนั่ง/ยืน มีแสง/เสียง/พื้นที่จำกัดไหม'],['2. Interface design','มี objects/actions อะไร response time การสั่งงานและ error handling เป็นอย่างไร'],['3. Construction & implementation','สร้าง prototype แล้ววนปรับจากผลทดลอง'],['4. Validation','ทำ task ได้ครบ รองรับ task variations ใช้ง่าย เรียนรู้ง่าย และผู้ใช้ยอมรับไหม']]))+
section('Golden rules 3 ข้อของ Theo Mandel',table(['หลัก','ตัวอย่างที่นำไปตอบข้อสอบได้'],[['Place the user in control','ยกเลิก/ย้อนกลับ/undo ได้ ไม่บังคับ action ที่ไม่จำเป็น รองรับ input ที่เหมาะกับผู้ใช้ ซ่อนรายละเอียดเทคนิค'],['Reduce the user’s memory load','แสดงตัวเลือกและประวัติ มี defaults ที่สมเหตุสมผล ไม่ให้จำ Booking ID เอง เปิดรายละเอียดทีละชั้น'],['Make the interface consistent','ปุ่ม/ศัพท์/ตำแหน่งสม่ำเสมอ บอกบริบทปัจจุบัน ไม่เปลี่ยนความหมาย shortcut ที่ผู้ใช้คุ้น']])+example('หน้าจอยกเลิกตั๋ว',p('แสดงรายการตั๋วให้เลือก → แสดงเงื่อนไขคืนเงินและยอด → ให้ผู้ใช้ยืนยันหรือกลับ → แสดงผลสำเร็จ หลักที่ใช้คือ control + memory load + consistency ไม่ใช่แค่เลือกสีให้สวย')))+
section('Low fidelity vs High fidelity',table(['','Low fidelity','High fidelity'],[['ลักษณะ','หยาบ รายละเอียดน้อย เช่นกระดาษ/wireframe','ใกล้ของจริง มีเนื้อหาและ interaction สมจริง'],['เป้าหมาย','คุยโครงสร้าง แนวคิดและ flow ตั้งแต่ต้น','ตรวจ usability/interaction และรายละเอียด'],['ข้อดี','แก้เร็ว ต้นทุนต่ำ','ทดลองงานใกล้ของจริง'],['ข้อควรจำ','digital wireframe ก็เป็น low fidelity ได้','ไม่จำเป็นต้องมี backend จริงหรือเขียนโค้ดครบ']])+p('Prototype ช่วยตรวจสอบและทำความเข้าใจ requirements โดยเฉพาะ UI ทั้ง visual looks และ logical/control flow ไม่ใช่หลักฐานว่าระบบ production เสร็จแล้ว'))+refs([[18,'4–25'],[8,'48'],[19,'1']])},
{id:'usecase',no:'06',title:'Use Case Diagram & Narrative',thai:'จาก “ใครทำอะไร” สู่คำบรรยายทีละขั้น',part:2,time:'25',summary:'Actor, Boundary, Association, Include, Extend และ Narrative 8 ช่อง',content:
section('อ่านโจทย์ด้วยคำถาม 3 ข้อ',list(['<b>ระบบอะไร?</b> กำหนดชื่อและขอบเขต','<b>ใครโต้ตอบกับระบบ?</b> Actor เป็นบทบาทของคนหรือระบบภายนอก','<b>เขาต้องการบรรลุเป้าหมายอะไร?</b> ใช้ชื่อกริยา + สิ่งที่ทำ เป็น Use case'])+p('Use case modeling เป็น scenario-based modeling ของ functional requirements จากมุมมอง actor ใช้ diagram คู่กับ narrative เพื่อตรวจความต้องการกับ stakeholders'))+
section('สัญลักษณ์และความสัมพันธ์',table(['ส่วน','ความหมาย / วิธีวาด'],[['Actor','stick figure อยู่นอกกรอบ มีชื่อบทบาท ระบบภายนอกเช่น Payment Gateway ก็เป็น actor'],['Use case','วงรีอยู่ในกรอบ ชื่อกริยา เช่น “ซื้อตั๋ว”'],['System boundary','กรอบพร้อมชื่อระบบ กำหนดสิ่งที่ระบบรับผิดชอบ'],['Association','เส้นทึบ actor ↔ use case สื่อว่ามี interaction ไม่ใช่ data flow'],['Generalization / Inheritance','เส้นทึบหัวสามเหลี่ยมโปร่งจากบทบาทเฉพาะไปบทบาททั่วไป'],['«include»','เส้นประหัวลูกศรโปร่ง จาก base ไป use case ที่นำพฤติกรรมมาใช้'],['«extend»','เส้นประหัวลูกศรโปร่ง จาก use case ที่เพิ่มพฤติกรรม ไป base use case']])+note('ชื่อในสไลด์','สไลด์บางหน้าใช้ includes/extends; notation UML มาตรฐานใช้ «include»/«extend» จำทิศลูกศรตาม L4 หน้า 19–20'))+
section('Include vs Extend: เริ่มลูกศรจากไหน',`<div id="relationship-diagram"></div>`+table(['ตัวอย่าง','ความสัมพันธ์','เหตุผล'],[['ซื้อตั๋ว → ชำระเงิน','«include»','นำพฤติกรรมการชำระเงินมาใช้ใน flow ซื้อสำเร็จ'],['แนบรูป → รายงานถนนชำรุด','«extend» [เลือกแนบรูป]','การแนบรูปเป็นพฤติกรรมเสริมเมื่อผู้ใช้เลือก รายงานหลักยังทำได้โดยไม่แนบ'],['เจ้าหน้าที่ขาย → ผู้ใช้ระบบ','Generalization (ตัวอย่างสมมติ)','บทบาทเฉพาะรับพฤติกรรมของบทบาททั่วไป']])+note('อย่าใช้เส้นเพราะเห็นเป็นงานย่อย','Include/Extend แสดงความสัมพันธ์ของพฤติกรรม ไม่ได้ใช้จัดหมวดหมู่รายงานหรือบอกลำดับก่อนหลังทุกขั้น Login อาจเป็น precondition แทนการ include ทุก use case เพราะไม่ใช่ login ใหม่ทุกครั้ง'))+
section('Narrative 8 ช่อง',table(['ช่อง','ต้องเขียนอะไร'],[['Use Case Name','ชื่อเดียวกับวงรีใน diagram'],['Primary Actor','ผู้เริ่มหรือผู้มีเป้าหมายหลัก'],['Goal in Context','ผลสำเร็จของ use case นี้สำหรับ actor'],['Precondition','สิ่งที่เป็นจริงก่อนเริ่ม'],['Trigger','เหตุการณ์ที่ทำให้เริ่ม use case'],['Scenario / Main flow','ลำดับ actor และ system โต้ตอบจนสำเร็จ'],['Exception','ระบุจุดที่เกิดเงื่อนไขผิดปกติ + ระบบตอบอย่างไร + กลับ/จบที่ไหน'],['Postcondition','สถานะ/ข้อมูลที่เปลี่ยนหลังสำเร็จ และสภาพหลังล้มเหลวเมื่อเกี่ยวข้อง']])+example('Precondition ไม่ใช่ Trigger',p('ขอยืมอุปกรณ์: “นักศึกษาเข้าสู่ระบบแล้ว” = Precondition · “นักศึกษากดส่งคำขอยืม” = Trigger · “คำขอถูกบันทึกเป็นรอตรวจพร้อม Request ID” = Postcondition')))+
section('วิธีทำข้อสอบ Part 2',list(['1. ขีดเส้นใต้ชื่อบทบาทและระบบภายนอก','2. วงกริยาที่เป็นเป้าหมาย เช่น ขอ/จอง/ตรวจ/จัดการ/ดูรายงาน','3. จัดตาราง actor กับ use case ให้ครบ','4. วาดกรอบ วงรี และ association แล้วเพิ่ม include/extend เฉพาะที่อธิบายเหตุผลได้','5. เลือก use case เขียน narrative ตรวจชื่อ goal main flow exception และ postcondition','6. เทียบทุก requirement กับ diagram/narrative และตรวจว่าไม่ได้เพิ่มสมมติฐานโดยไม่บอก'])+p('ตัวอย่างเต็มอยู่ใน “ตัวอย่างจากโจทย์” โดยเฉพาะ Zoo, PHTRS และ UEBS'))+refs([[11,'5–24'],[19,'33–37'],[9,''],[2,'3–4']])},
{id:'context',no:'07',title:'Context DFD',thai:'มองข้อมูลที่ข้ามขอบเขตระบบ',part:2,time:'25',summary:'Process 0, External entities, ลูกศรข้อมูล และการตรวจความสอดคล้อง',content:
section('Context diagram ตอบว่าอะไรเข้า อะไรออก',p('DFD แสดงข้อมูลที่ไหลเข้า process และถูกแปลงเป็น output · Context diagram แสดงทั้งระบบเป็น <b>Process 0 เพียงหนึ่ง process</b> พร้อม external entities และ data flows ที่ข้ามขอบเขตระบบ')+note('ขอบเขตสอบ','รูปและ Midterm Guideline ระบุ Context DFD ชัดเจน ส่วน DFD Level 1/2, PSPEC และ CSPEC มีในไฟล์เรียน จึงเก็บเป็นบทเสริมเพื่อความเข้าใจ ไม่อ้างว่าเป็นงานวาดที่ต้องออกสอบแน่นอน'))+
section('สัญลักษณ์ DFD และกฎ',table(['ส่วน','รูป / การตั้งชื่อ'],[['External entity','สี่เหลี่ยม · คน/หน่วยงาน/ระบบภายนอกที่ส่งหรือรับข้อมูล'],['Process','วงกลมหรือสี่เหลี่ยมมุมมนตาม notation ที่เลือก · แปลง input เป็น output'],['Data flow','ลูกศรมีทิศทางและชื่อข้อมูล เช่น “คำขอยกเลิกตั๋ว”'],['Data store','เส้นคู่/สี่เหลี่ยมเปิดข้างตาม notation · ใช้เก็บข้อมูลถาวรใน DFD รายละเอียด']])+list(['Context มี process เดียว หมายเลข 0 และไม่มี internal data store','ทุก flow ต้องเริ่มหรือจบที่ process และมีชื่อ','ห้าม entity → entity, entity → data store หรือ data store → data store โดยไม่ผ่าน process','Process ต้องมี input และ output ที่สมเหตุสมผล','ชื่อ flow เป็นข้อมูล/คำนาม ไม่ใช่ชื่อคำสั่งคลิก และไม่ใช่สิ่งของจริงที่ส่งกัน']))+
section('Use case กับ Data flow ใช้คนละภาษา',table(['ข้อความในโจทย์','ชื่อ Use case','ชื่อ Data flow'],[['ผู้เยี่ยมชมเลือกประเภทและวันเข้าชม','ซื้อตั๋ว','คำขอซื้อตั๋ว (ประเภท จำนวน วันที่)'],['ระบบออก QR หลังชำระสำเร็จ','ออกตั๋ว (พฤติกรรมใน flow)','ตั๋ว / Booking ID / QR Code'],['หัวหน้าเลือกดูรายงาน','ดูรายงาน','คำขอรายงาน / รายงานสรุป'],['Payment Gateway ส่งผลกลับ','ชำระเงิน (มี gateway ร่วม)','ผลการชำระเงิน']])+p('Data packet: ข้อมูลที่ไปด้วยกันจัดเป็น flow เดียวได้ เช่น “คำขอซื้อตั๋ว” ครอบคลุมประเภท จำนวน วัน ไม่จำเป็นต้องลากลูกศรใหม่ทุก field'))+
section('วาด Context ทีละขั้น',list(['1. เขียนชื่อระบบใน Process 0 ตรงกลาง','2. ลิสต์ external entities จากผู้ผลิต/ผู้รับข้อมูล','3. สร้างตาราง “Entity → ระบบ” และ “ระบบ → Entity” จากแต่ละประโยคในโจทย์','4. วาดลูกศรทีละคู่ ใช้ชื่อก้อนข้อมูล วาง label ให้ไม่ทับเส้น','5. ตรวจทิศทางกลับไปที่ตาราง และไล่ความครอบคลุมกับโจทย์'])+p('ไม่ต้องฝืนให้ทุก entity มีทั้ง input และ output ถ้าโจทย์มี interaction ทางเดียว แต่ process ทั้งระบบต้องมี input/output · ระบบภายนอกไม่ได้กลายเป็น internal เพียงเพราะถูกเชื่อมต่อ'))+
section('Black hole, Miracle, Gray hole',table(['ข้อผิดพลาด','ตัวอย่าง'],[['Black hole','มีคำขอซื้อเข้า แต่ไม่มีผลลัพธ์ใดออก'],['Miracle','ออกยอดชำระโดยไม่มี input ที่ใช้คำนวณ'],['Gray hole','รับแค่ชื่อลูกค้า แต่คำนวณราคาตั๋วได้ ทั้งที่ไม่มีประเภท/จำนวน/ราคา']])+p('ตรวจทั้งจำนวน input/output และความเพียงพอของข้อมูล output ต้องอธิบายได้จาก input/data ที่ process ใช้'))+
section('Consistency ระหว่างโมเดล',p('Use case ซื้อบัตร → Narrative ต้องมีข้อมูลเลือกบัตรและผลชำระ → Context ต้องมีคำขอซื้อและผลตั๋วไปยังผู้เกี่ยวข้อง ชื่ออาจต่างตามหน้าที่โมเดล แต่ข้อมูลและขอบเขตต้องไม่ขัดกัน')+example('อย่าสลับลูกศร',p('“ข้อมูลการรับ–คืนอุปกรณ์” เจ้าหน้าที่เป็นผู้บันทึก จึงต้องเป็น เจ้าหน้าที่ → ระบบ ส่วน “รายละเอียดคำขอที่ต้องตรวจ” เป็น ระบบ → เจ้าหน้าที่')))+refs([[14,'7–33'],[19,'39–46'],[25,'3–14'],[3,'2']])},
{id:'extra',no:'08',title:'Modeling · อ่านเสริม',thai:'แยกโมเดลและเชื่อมรายละเอียด',part:0,time:'10',summary:'ERD, Cardinality, DFD hierarchy, PSPEC และ CSPEC',content:
note('ลำดับความสำคัญ','อ่านหลังฝึก Use case diagram, Narrative และ Context DFD แล้ว หัวข้อนี้มีในชุดไฟล์ แต่ภาพขอบเขตสอบไม่ได้ระบุให้วาด ERD หรือ DFD Level 1/2 โดยตรง')+
section('โมเดลแต่ละชนิดตอบคนละคำถาม',table(['Model','คำถาม','ตัวอย่าง'],[['Scenario-based / Use case','ใครทำอะไรกับระบบ','ผู้เยี่ยมชมซื้อตั๋ว'],['Flow / DFD','ข้อมูลเคลื่อนและถูกแปลงอย่างไร','คำขอซื้อ → ระบบ → ตั๋ว'],['Data / ERD','เก็บอะไร และสัมพันธ์กันอย่างไร','Customer, Booking, Ticket'],['Class model','classes มี attributes/operations และสัมพันธ์กันอย่างไร','Booking มี create/cancel'],['Behavioral model','ระบบตอบสนอง event/state อย่างไร','Pending → Paid → Cancelled']]))+
section('ERD, Cardinality และ Modality',p('Entity คือสิ่งที่ต้องเก็บข้อมูล Attribute คือรายละเอียด Relationship คือความสัมพันธ์ · Cardinality บอกจำนวนสูงสุด (หนึ่ง/หลาย) และ Modality บอกขั้นต่ำ (ศูนย์/หนึ่ง) ตามวิธีอธิบายในชุดสรุป')+example('Customer กับ Booking (ตัวอย่างสมมติ)',p('Customer หนึ่งคนมี Booking ได้ <b>0..*</b> รายการ = อาจไม่เคยจองหรือจองหลายครั้ง ส่วน Booking แต่ละรายการเป็นของ Customer <b>1..1</b> คน ถ้าออกแบบให้ใช้บัญชีเสมอ ข้อนี้เป็นสมมติฐาน ไม่ควรใช้กับโจทย์ที่ไม่บังคับบัญชีโดยอัตโนมัติ')))+
section('DFD hierarchy และ Balancing',p('รายวิชานี้เรียก <b>Context = Level 0</b> แล้วแยกเป็น Level 1 (1,2,3,…) Level 2 (1.1,1.2,…) และ Level 3 (1.1.1,…)')+p('Balancing คือ input/output ที่ข้ามขอบเขตของ parent ต้องคงอยู่ใน child แม้แยกข้อมูลเป็นหลาย flow ได้หากรวมแล้วองค์ประกอบตรงกัน child เพิ่ม process และ flow ภายในได้')+note('ยึด convention ของรายวิชา','L6 หน้า 30 กำหนด external entities ให้แสดงใน context เท่านั้นสำหรับรูปแบบงานของวิชานี้ ตำราอื่นอาจมีการวาดซ้ำในระดับรายละเอียดได้ และบางตำราใช้คำว่า Level 0 ต่างกัน อย่าสลับ convention ในคำตอบ'))+
section('Process specification และ Control specification',table(['ส่วน','หน้าที่ / รูปแบบ'],[['PSPEC','อธิบายตรรกะภายใน primitive process ด้วย narrative, pseudocode/PDL, equations, tables หรือ charts'],['Structured English','ใช้ natural language กับโครงสร้าง sequence/condition/iteration เพื่ออธิบายตรรกะ'],['Decision table','แจกแจง conditions กับ actions ของ policy'],['Control flow','สัญญาณ/event ณ จุดเวลา สไลด์ใช้เส้นประ ต่างจาก data flow'],['CSPEC','อธิบายพฤติกรรม/การควบคุม เช่น state diagram, state transition table, decision/activation table']])+example('Decision table ค่าปรับ UEBS',table(['คืนช้า?','เสียหาย?','Action'],[['ไม่','ไม่','ปิดรายการตาม flow'],['ใช่','ไม่','คิดค่าปรับ 50 × จำนวนวันล่าช้า'],['ไม่','ใช่','บันทึกค่าซ่อม'],['ใช่','ใช่','คิดค่าปรับ + บันทึกค่าซ่อม']])+p('วันที่เริ่มนับ/การปัดเศษและเงื่อนไขปิดรายการเมื่อค้างชำระต้องถามเพิ่ม ไม่เดาเอง')))+refs([[8,'50–51'],[14,'17–34'],[15,'10–24'],[31,'']])}
];
